using System;
using Framework.AI.Core;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.AI.Tactics;
using Game.Map;
using Game.Stage;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// 敵AIの戦術評価システムを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyTacticalEvaluatorTest
        : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("テスト用ステージ管理Prefab。")]
        private MazeStageManager stageManagerPrefab;

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 32;

        /// <summary>
        /// 敵の初期座標。
        /// </summary>
        private static readonly Vector2Int StartPosition =
            new Vector2Int(1, 1);

        /// <summary>
        /// プレイヤーの識別子。
        /// </summary>
        private readonly Guid playerId = Guid.NewGuid();

        /// <summary>
        /// 脅威の識別子。
        /// </summary>
        private readonly Guid threatId = Guid.NewGuid();

        /// <summary>
        /// テスト用ステージ管理インスタンス。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用移動コントローラー。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用パラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト用敵AIコンテキスト。
        /// </summary>
        private MazeEnemyContext context;

        /// <summary>
        /// テスト用認識制御システム。
        /// </summary>
        private MazeEnemyPerceptionController perception;

        /// <summary>
        /// テスト対象の戦術評価システム。
        /// </summary>
        private MazeEnemyTacticalEvaluator evaluator;

        /// <summary>
        /// 開始時にテストを実行する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "Play Modeで実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            try
            {
                Prepare();
                TestInitialization();

                Prepare();
                TestChase();

                Prepare();
                TestPrediction();

                Prepare();
                TestIntercept();

                Prepare();
                TestEscape();

                Prepare();
                TestReturn();

                Prepare();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemyTacticalEvaluator テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト環境を生成する。
        /// </summary>
        private void Prepare()
        {
            Cleanup();

            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用ステージPrefabが未設定です。");
            }

            stageManager = Instantiate(stageManagerPrefab);

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "ステージ生成に失敗しました。");
            }

            if (stageManager.Map.Width < 10 ||
                stageManager.Map.Height < 5)
            {
                throw new InvalidOperationException(
                    "10×5以上のマップが必要です。");
            }

            // 固定条件で評価するため全セルを床にする。
            stageManager.Map.Fill(MazeCell.CreateFloor());

            // ステージの即時クリアを防止する。
            stageManager.Map.SetCell(
                Vector2Int.zero,
                MazeCell.CreateFloor(MazeCellFlags.Gem));

            movementObject =
                new GameObject("TacticalTest_Movement");

            movement = movementObject
                .AddComponent<GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                StartPosition);

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 4f);

            parameters.SetBaseValue(
                MazeEnemyParameter.ChaseSpeedMultiplier, 1f);

            parameters.SetBaseValue(
                MazeEnemyParameter.EscapeSpeedMultiplier, 1f);

            parameters.SetBaseValue(
                MazeEnemyParameter.DetectionRange, 20f);

            parameters.SetBaseValue(
                MazeEnemyParameter.ThreatDetectionRange, 20f);

            parameters.SetBaseValue(
                MazeEnemyParameter.TacticalIntelligence, 1f);

            parameters.SetBaseValue(
                MazeEnemyParameter.PredictionTime, 2f);

            parameters.SetBaseValue(
                MazeEnemyParameter.TerritoryRadius, 2f);

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality, 1f);

            var agentContext =
                new AgentContext<MazeEnemyParameter>(
                    "TacticalTest",
                    parameters);

            context = new MazeEnemyContext(
                agentContext,
                stageManager,
                movement,
                StartPosition);

            perception =
                new MazeEnemyPerceptionController(context);

            evaluator =
                new MazeEnemyTacticalEvaluator(context);

            if (!stageManager.StartStage())
            {
                throw new InvalidOperationException(
                    "ステージ開始に失敗しました。");
            }
        }

        /// <summary>
        /// 指定条件の対象を認識する。
        /// </summary>
        /// <param name="position">対象座標</param>
        /// <param name="direction">移動方向</param>
        /// <param name="speed">移動速度</param>
        /// <param name="type">対象種類</param>
        /// <returns>対象の観測情報</returns>
        private MazeEnemyTargetObservation Observe(
            Vector2Int position,
            Vector2Int direction,
            float speed,
            MazeEnemyTargetType type =
                MazeEnemyTargetType.Player)
        {
            Guid id =
                type == MazeEnemyTargetType.Player
                    ? playerId
                    : threatId;

            var snapshot =
                new MazeEnemyTargetSnapshot(
                    id,
                    type,
                    position,
                    direction,
                    speed);

            if (!perception.UpdatePerception(
                    new[] { snapshot }) ||
                !perception.TryGetObservation(
                    id,
                    out var observation))
            {
                throw new InvalidOperationException(
                    "テスト対象を認識できませんでした。");
            }

            return observation;
        }

        /// <summary>
        /// 初期化と入力検証を行う。
        /// </summary>
        private void TestInitialization()
        {
            bool initial =
                evaluator.IsValid &&
                !evaluator.IsDisposed &&
                ReferenceEquals(
                    evaluator.Context, context);

            Debug.Assert(initial, "初期状態", this);
            Check(initial, "初期状態");

            bool origin =
                evaluator.Origin == StartPosition &&
                evaluator.Refresh();

            Debug.Assert(origin, "探索開始座標", this);
            Check(origin, "探索開始座標");

            bool invalid =
                !evaluator.TryEvaluateChase(
                    default, out var result) &&
                !result.IsValid;

            Debug.Assert(invalid, "無効な観測情報の拒否", this);
            Check(invalid, "無効な観測情報の拒否");

            bool nullRejected = false;

            try
            {
                new MazeEnemyTacticalEvaluator(null);
            }
            catch (ArgumentNullException)
            {
                nullRejected = true;
            }

            Debug.Assert(nullRejected, "null依存の拒否", this);
            Check(nullRejected, "null依存の拒否");
        }

        /// <summary>
        /// 直接追跡を検証する。
        /// </summary>
        private void TestChase()
        {
            var target = Observe(
                new Vector2Int(5, 1),
                Vector2Int.right,
                2f);

            bool chase =
                evaluator.TryEvaluateChase(
                    target, out var result) &&
                result.IsValid &&
                result.Type == MazeEnemyTacticalType.Chase;

            Debug.Assert(chase, "直接追跡評価", this);
            Check(chase, "直接追跡評価");

            bool destination =
                result.Destination == new Vector2Int(5, 1) &&
                result.Distance == 4;

            Debug.Assert(destination, "追跡目的地と距離", this);
            Check(destination, "追跡目的地と距離");

            bool arrival =
                Mathf.Approximately(
                    result.ArrivalTime, 1f);

            Debug.Assert(arrival, "追跡到達時間", this);
            Check(arrival, "追跡到達時間");

            stageManager.Map.SetCell(
                new Vector2Int(3, 1),
                MazeCell.CreateWall());

            bool detour =
                evaluator.TryEvaluateChase(
                    target, out var detourResult) &&
                detourResult.Distance == 6;

            Debug.Assert(detour, "壁を迂回する経路距離", this);
            Check(detour, "壁を迂回する経路距離");

            perception.UpdatePerception(
                Array.Empty<MazeEnemyTargetSnapshot>());

            bool remembered =
                perception.TryGetObservation(
                    playerId, out var memory) &&
                memory.IsRemembered &&
                evaluator.TryEvaluateChase(
                    memory, out var memoryResult) &&
                memoryResult.Destination ==
                    target.LastKnownPosition;

            Debug.Assert(remembered, "記憶座標への追跡", this);
            Check(remembered, "記憶座標への追跡");

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 0f);

            bool stopped =
                !evaluator.TryEvaluateChase(
                    target, out _);

            Debug.Assert(stopped, "移動速度0の追跡拒否", this);
            Check(stopped, "移動速度0の追跡拒否");
        }

        /// <summary>
        /// 移動先予測を検証する。
        /// </summary>
        private void TestPrediction()
        {
            var target = Observe(
                new Vector2Int(3, 1),
                Vector2Int.right,
                2f);

            bool predicted =
                evaluator.TryPredictPosition(
                    target, 2f,
                    out var position,
                    out int distance) &&
                position == new Vector2Int(7, 1) &&
                distance == 4;

            Debug.Assert(predicted, "直進移動予測", this);
            Check(predicted, "直進移動予測");

            stageManager.Map.SetCell(
                new Vector2Int(5, 1),
                MazeCell.CreateWall());

            bool wall =
                evaluator.TryPredictPosition(
                    target, 2f,
                    out var wallPosition,
                    out int wallDistance) &&
                wallPosition == new Vector2Int(4, 1) &&
                wallDistance == 1;

            Debug.Assert(wall, "壁による予測停止", this);
            Check(wall, "壁による予測停止");

            bool zero =
                evaluator.TryPredictPosition(
                    target, 0f,
                    out var zeroPosition,
                    out int zeroDistance) &&
                zeroPosition == target.LastKnownPosition &&
                zeroDistance == 0;

            Debug.Assert(zero, "予測時間0", this);
            Check(zero, "予測時間0");

            bool negative =
                !evaluator.TryPredictPosition(
                    target, -1f, out _, out _);

            Debug.Assert(negative, "負の予測時間拒否", this);
            Check(negative, "負の予測時間拒否");

            bool nan =
                !evaluator.TryPredictPosition(
                    target, float.NaN, out _, out _);

            Debug.Assert(nan, "非数値の予測時間拒否", this);
            Check(nan, "非数値の予測時間拒否");

            var stationary = Observe(
                new Vector2Int(3, 1),
                Vector2Int.zero,
                0f);

            bool stationaryPassed =
                evaluator.TryPredictPosition(
                    stationary, 2f,
                    out var stationaryPosition,
                    out int stationaryDistance) &&
                stationaryPosition ==
                    stationary.LastKnownPosition &&
                stationaryDistance == 0;

            Debug.Assert(stationaryPassed, "停止対象の予測", this);
            Check(stationaryPassed, "停止対象の予測");
        }

        /// <summary>
        /// 迎撃戦術を検証する。
        /// </summary>
        private void TestIntercept()
        {
            var target = Observe(
                new Vector2Int(3, 1),
                Vector2Int.right,
                2f);

            bool intercept =
                evaluator.TryEvaluateIntercept(
                    target, out var result) &&
                result.IsValid &&
                result.Type ==
                    MazeEnemyTacticalType.Intercept;

            Debug.Assert(intercept, "迎撃候補の取得", this);
            Check(intercept, "迎撃候補の取得");

            bool timing =
                result.ArrivalTime <=
                    result.TargetArrivalTime;

            Debug.Assert(timing, "迎撃到達時間の比較", this);
            Check(timing, "迎撃到達時間の比較");

            bool ahead =
                result.Destination.x >
                    target.LastKnownPosition.x &&
                result.Destination.y ==
                    target.LastKnownPosition.y;

            Debug.Assert(ahead, "進行先への迎撃", this);
            Check(ahead, "進行先への迎撃");

            parameters.SetBaseValue(
                MazeEnemyParameter.TacticalIntelligence, 0f);

            bool intelligence =
                !evaluator.TryEvaluateIntercept(
                    target, out _);

            Debug.Assert(intelligence, "戦術知能0の迎撃拒否", this);
            Check(intelligence, "戦術知能0の迎撃拒否");

            parameters.SetBaseValue(
                MazeEnemyParameter.TacticalIntelligence, 1f);

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 0.5f);

            bool slow =
                !evaluator.TryEvaluateIntercept(
                    target, out _);

            Debug.Assert(slow, "到達不能な迎撃候補の拒否", this);
            Check(slow, "到達不能な迎撃候補の拒否");

            parameters.SetBaseValue(
                MazeEnemyParameter.MoveSpeed, 4f);

            perception.UpdatePerception(
                Array.Empty<MazeEnemyTargetSnapshot>());

            bool hidden =
                perception.TryGetObservation(
                    playerId, out var memory) &&
                memory.IsRemembered &&
                !evaluator.TryEvaluateIntercept(
                    memory, out _);

            Debug.Assert(hidden, "未視認対象への迎撃抑制", this);
            Check(hidden, "未視認対象への迎撃抑制");
        }

        /// <summary>
        /// 逃走戦術を検証する。
        /// </summary>
        private void TestEscape()
        {
            var threat = Observe(
                new Vector2Int(2, 1),
                Vector2Int.left,
                3f,
                MazeEnemyTargetType.Threat);

            bool escape =
                evaluator.TryEvaluateEscape(
                    threat, 4, out var result) &&
                result.IsValid &&
                result.Type ==
                    MazeEnemyTacticalType.Escape;

            Debug.Assert(escape, "逃走地点の取得", this);
            Check(escape, "逃走地点の取得");

            bool safety =
                result.SafetyDistance > 1 &&
                result.Destination != StartPosition;

            Debug.Assert(safety, "脅威との距離拡大", this);
            Check(safety, "脅威との距離拡大");

            bool limit =
                result.Distance > 0 &&
                result.Distance <= 4;

            Debug.Assert(limit, "逃走探索距離制限", this);
            Check(limit, "逃走探索距離制限");

            bool invalid =
                !evaluator.TryEvaluateEscape(
                    threat, 0, out _);

            Debug.Assert(invalid, "無効な逃走距離拒否", this);
            Check(invalid, "無効な逃走距離拒否");
        }

        /// <summary>
        /// 縄張り帰還を検証する。
        /// </summary>
        private void TestReturn()
        {
            bool inside =
                !evaluator.TryEvaluateReturn(out _);

            Debug.Assert(inside, "縄張り内では帰還不要", this);
            Check(inside, "縄張り内では帰還不要");

            if (!movement.TryTeleport(
                new Vector2Int(6, 1)))
            {
                throw new InvalidOperationException(
                    "テスト用移動に失敗しました。");
            }

            bool outside =
                evaluator.TryEvaluateReturn(
                    out var result) &&
                result.Type ==
                    MazeEnemyTacticalType.ReturnToTerritory;

            Debug.Assert(outside, "縄張り外からの帰還", this);
            Check(outside, "縄張り外からの帰還");

            bool nearest =
                result.Destination ==
                    new Vector2Int(3, 1) &&
                result.Distance == 3;

            Debug.Assert(nearest, "最寄りの縄張り内地点", this);
            Check(nearest, "最寄りの縄張り内地点");

            parameters.SetBaseValue(
                MazeEnemyParameter.Territoriality, 0f);

            bool disabled =
                !evaluator.TryEvaluateReturn(out _);

            Debug.Assert(disabled, "縄張り意識0の帰還抑制", this);
            Check(disabled, "縄張り意識0の帰還抑制");
        }

        /// <summary>
        /// キャッシュ更新と破棄処理を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            var target = Observe(
                new Vector2Int(3, 1),
                Vector2Int.right,
                2f);

            evaluator.TryEvaluateChase(
                target, out var before);

            stageManager.Map.SetCell(
                new Vector2Int(2, 1),
                MazeCell.CreateWall());

            bool refresh =
                evaluator.TryEvaluateChase(
                    target, out var after) &&
                before.Distance == 2 &&
                after.Distance == 4;

            Debug.Assert(refresh, "地形変更後の距離再計算", this);
            Check(refresh, "地形変更後の距離再計算");

            evaluator.Dispose();
            evaluator.Dispose();

            bool disposed =
                evaluator.IsDisposed &&
                !evaluator.IsValid &&
                !evaluator.Refresh() &&
                !evaluator.TryEvaluateChase(
                    target, out _) &&
                context.IsValid &&
                !parameters.IsDisposed;

            Debug.Assert(disposed, "破棄処理と外部所有権維持", this);
            Check(disposed, "破棄処理と外部所有権維持");
        }

        /// <summary>
        /// テスト環境を解放する。
        /// </summary>
        private void Cleanup()
        {
            evaluator?.Dispose();
            evaluator = null;

            perception?.Dispose();
            perception = null;

            context?.Dispose();
            context = null;

            parameters?.Dispose();
            parameters = null;

            if (movementObject != null)
            {
                movementObject.SetActive(false);
                Destroy(movementObject);

                movementObject = null;
            }

            movement = null;

            if (stageManager != null)
            {
                stageManager.gameObject.SetActive(false);
                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// オブジェクト破棄時に資源を解放する。
        /// </summary>
        private void OnDestroy()
        {
            Cleanup();
        }

        /// <summary>
        /// 個別テスト結果を出力する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
